export function getUKMLAProfile(acNo: number): MLAProfile | undefined {
  return UK_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getUKMLAsByParty(party: string): MLAProfile[] {
  return UK_MLA_PROFILES.filter(p => p.party === party);
}

export function getUKFemaleMLAs(): MLAProfile[] {
  return UK_MLA_PROFILES.filter(p => p.gender === 'F');
}
